  "investigate": [
    {
      "tool": "logs",
      "service": "payment-service",
      "level": "ERROR",
      "contains": "order",
      "why": "Check for errors in payment-service related to order lookup or confirmation, which would explain why payments are captured without orders"
    },
    {
      "tool": "sql",
      "query": "SELECT id, order_id, created_at FROM payments WHERE order_id NOT IN (SELECT id FROM orders WHERE status = 'confirmed') AND created_at >= :now - 600 ORDER BY created_at LIMIT 11",
      "why": "Get details of the violating payments to see if they are missing orders entirely or orders are not confirmed, and check timing relative to deploy"
    }
  ],
  "hypotheses": [
    {
      "service": "payment-service",
      "kind": "bad_deploy",
      "mechanism": "The deploy of payment-service v2.0 at t=490 introduced a fault that causes it to capture payments without properly confirming orders, leading to violations of I1_payment_has_order.",
      "supporting": ["E1", "E11", "E9", "E10"],
      "refuting": [],
      "explains": ["I1_payment_has_order"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "payment-service"}},
        {"action": "replay_payment_confirmations", "params": {}}
      ]
    }
  ],
  "summary": "A bad deploy of payment-service at t=490 caused it to capture payments without confirming orders, violating I1_payment_has_order."
}
